import gurobipy as gp
from gurobipy import GRB
shelves = []
resource_capacity = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'resource_id' in v and 'resource_capacity' in v:
        rid = str(v['resource_id'])
        shelves.append(rid)
        resource_capacity[rid] = int(v['resource_capacity'])
products = []
item_value = {}
resource_requirement = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'item_name' in v and 'item_value' in v and ('resource_requirement' in v):
        pid = str(v['item_name'])
        products.append(pid)
        item_value[pid] = int(v['item_value'])
        resource_requirement[pid] = int(v['resource_requirement'])
if len(shelves) == 0 or len(products) == 0:
    raise ValueError('Missing shelves or products data.')
for rid in shelves:
    if rid not in resource_capacity:
        raise ValueError(f'Missing capacity for shelf {rid}')
for pid in products:
    if pid not in item_value or pid not in resource_requirement:
        raise ValueError(f'Missing value or requirement for product {pid}')
m = gp.Model('BigMart_Shelf_Allocation')
x = m.addVars(shelves, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((item_value[pid] * x[rid, pid] for rid in shelves for pid in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((resource_requirement[pid] * x[rid, pid] for pid in products)) <= resource_capacity[rid] for rid in shelves), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')